metadata.dynamic_expression:
# Shared Linux/macOS workload: N generators + N floating builds.
# Give the leaf a different output name so the generator does not rewrite its
# placeholder while substituting its own $out into the serialized payload.
{ nodes, shape, shell }:
assert builtins.isInt nodes && nodes > 0;
assert builtins.elem shape [ "chain" "wide" ];
let
  seed = builtins.toFile "seed" "seed\n";
  make = index: previous:
    let
      leaf = derivation {
        name = "leaf-${toString index}";
        system = builtins.currentSystem;
        builder = shell;
        outputs = [ "result" ];
        __contentAddressed = true;
        outputHashMode = "recursive";
        outputHashAlgo = "sha256";
        inherit seed;
        args = [ "-c" ''set -eu; read -r value < "$seed"; test "$value" = seed; printf 'value-${toString index}' > "$result"'' ];
      };
    in derivation {
      name = "leaf-${toString index}.drv";
      system = builtins.currentSystem;
      builder = shell;
      __contentAddressed = true;
      outputHashMode = "text";
      outputHashAlgo = "sha256";
      inherit seed previous;
      payload = builtins.unsafeDiscardStringContext (builtins.readFile leaf.drvPath);
      args = [ "-c" ''set -eu; read -r value < "$seed"; test "$value" = seed; if test -n "$previous"; then test -s "$previous"; fi; printf '%s' "$payload" > "$out"'' ];
    };
  generators = builtins.genList (index: make index (
    if shape == "chain" && index > 0
    then builtins.outputOf (builtins.elemAt generators (index - 1)).outPath "result"
    else ""
  )) nodes;
  targets = if shape == "chain" then [ (builtins.elemAt generators (nodes - 1)) ] else generators;
in map (generator: generator.drvPath + "^out^result") targets

metadata.shared_expression:
# Each output retains references to its two predecessors, forming overlapping
# transitive closures. Request every node so verification checks every byte.
{ count ? 64, nonce ? "manual", system ? builtins.currentSystem }:
assert builtins.isInt count && count > 0;
let
  graph = builtins.genList (index:
    let
      dependencies = builtins.genList
        (offset: builtins.elemAt graph (index - offset - 1))
        (if index < 2 then index else 2);
    in derivation {
      name = "shared-${nonce}-${toString index}";
      inherit system;
      builder = "/bin/sh";
      previous = dependencies;
      value = "value-${toString index}";
      args = [ "-c" ''
        set -eu
        printf '%s\n' "$value" > "$out"
        for dependency in $previous; do
          test -s "$dependency"
          printf '%s\n' "$dependency" >> "$out"
        done
      '' ];
      preferLocalBuild = true;
      allowSubstitutes = false;
    }) count;
in graph

metadata.expression:
# No nixpkgs dependency: the host /bin/sh reads one declared store input and
# writes one output. Distinct names ensure these are separate derivations.
{ count ? 64, nonce ? "manual", system ? builtins.currentSystem }:
assert builtins.isInt count && count > 0;
let
  input = builtins.toFile "build-benchmark-input" "casita\n";
  script = builtins.toFile "build-benchmark.sh" ''
    set -eu
    read value < "$input"
    printf '%s' "$value" > "$out"
  '';
in
builtins.genList (index: derivation {
  name = "build-benchmark-${nonce}-${toString index}";
  inherit system input;
  builder = "/bin/sh";
  args = [ script ];
  preferLocalBuild = true;
  allowSubstitutes = false;
}) count
